private readonly ConcurrentDictionary<string, byte> _seen = new();

public async Task HandleAsync(OrderMessage msg, CancellationToken ct)
{
    if (!_seen.TryAdd(msg.IdempotencyKey, 0)) return;   // duplicate: absorb
    await using var tx = await _db.Database.BeginTransactionAsync(ct);
    _db.Inbox.Add(new InboxEntry(msg.IdempotencyKey));  // durable claim, UNIQUE index
    ApplyEffects(msg);                                  // same transaction
    await _db.SaveChangesAsync(ct);
    await tx.CommitAsync(ct);
}
